/* The pose viewer: the view takes the panel's whole height, its controls and key in a quiet bar
   along its top edge, just inside the rule. On phones the bar sits above the view. */
.viewer {
  position: relative;
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
}

.toolbar {
  position: absolute;
  top: 1px;
  right: 0;
  left: 0;
  z-index: 1;
  display: flex;
  flex-wrap: wrap;
  gap: 0 var(--space-24);
  align-items: center;
  padding: var(--space-4) var(--space-12);
  border-bottom: 1px solid var(--color-rule);
  background: color-mix(in srgb, var(--color-paper) 88%, transparent);
}

.toggle {
  display: inline-flex;
  gap: var(--space-8);
  align-items: center;
  height: 32px;
  padding: 0;
  border: 0;
  background: none;
  font-size: var(--text-body-sm);
  font-weight: var(--weight-medium);
}

/* A check box drawn in ink: filled with a paper inset when on. */
.box {
  position: relative;
  flex: none;
  width: 14px;
  height: 14px;
  border: 1.5px solid var(--color-ink);
  border-radius: 1px;
}

.toggle[aria-pressed="true"] .box::after {
  position: absolute;
  inset: 2px;
  background: var(--color-ink);
  content: "";
}

/* The crystal position's toggle is also its key: its box is in the redock colour. */
.toggle[data-swatch="overlay"] .box {
  border-color: var(--color-redock);
}

.toggle[data-swatch="overlay"][aria-pressed="true"] .box::after {
  background: var(--color-redock);
}

.toggle:hover .box {
  background: var(--color-hover);
}

