    expect(polarContacts([drugO], protein)).toEqual([]);
    expect(polarContacts([drugC], [{ x: 2.9, y: 0, z: 0, elem: "O", resn: "ASP", resi: 3 }])).toEqual(
      [],
    );
  });
});

