/*
 * Panels that scroll show no scroll bar, so a bar never cuts into the figure: they still scroll
 * by wheel, trackpad, touch and keyboard, and a row cut at the panel's edge (or its fade) says
 * there is more. The page's own scroll bar, on the root, stays.
 */
body * {
  scrollbar-width: none;
}

body *::-webkit-scrollbar {
  display: none;
}

/*
 * The quiet cue in place of the bar: a panel that scrolls fades at its foot while there is more
 * below, and the fade lifts as the end comes into view. A panel whose content fits never fades.
 * Compose it into a scrolling panel's class: `composes: scroll-fade from global;`. Where scroll
 * timelines aren't supported, the panel simply doesn't fade.
 */
@property --scroll-fade {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

.scroll-fade {
  mask-image: linear-gradient(
